def get_trade_list(user_id, op_station=None, strategy_type=None, mode=None):
    """
    查询交易文件信息

    :param user_id: 用户ID
    :type user_id: str
    :param op_station: 站点信息
    :type op_station: str
    :param strategy_type: 策略类型。1.传实际策略类型时返回对应的交易信息；
                                  2.传入"trade"时返回交易状态为"0"或"5"的交易信息；
                                  3.传入"current_trade"时返回交易状态为"0"或"5"且ip等于当前服务器IP的交易信息；
                                  4.传入"strategy_active_deleted"时返回交易状态为"0"（运行中）、"2"（删除）或"5"（待重启）的交易信息，
                                    包含已删除交易，且仅返回channel_type为"app"的交易，
                                    对于backtestContentId相同的交易只保留最后一条；
    :type strategy_type: str
    :return: 交易信息
    :rtype: dict
    """
    trade_list_file = os.path.join(TRADE_DIR_PATH, user_id, SIM_TRADING_LIST_FILE)
    delete_trade_list_file = os.path.join(TRADE_DIR_PATH, user_id, DELETE_SIM_TRADING_LIST_FILE)
    trades = []
    try:
        if strategy_type == 'strategy_active_deleted' and os.path.exists(delete_trade_list_file):
            try:
                with FileLock(delete_trade_list_file, mode='shared'):
                    delete_csv_reader = FileIO(delete_trade_list_file).read(return_type='dict_reader')
                for item in delete_csv_reader:
                    if item['status'] == '2':
                        trades.append(item)
            except BaseException:
                app_log.error(f'读取{delete_trade_list_file!s}文件失败，错误原因：{get_traceback_message()!s}')
        if os.path.exists(trade_list_file):
            with FileLock(trade_list_file, mode='shared'):
                csv_reader = FileIO(trade_list_file).read(return_type='dict_reader')
            for item in csv_reader:
                if strategy_type is None:
                    if mode == 'custom':
                        if item['status'] != '2' and (not op_station or item['op_station'] == op_station) and item['strategyType'] in list(CUSTOM_STRATEGY_TYPE_DICT.values()):
                            trades.append(item)
                        else:
                            continue
                        continue
                    elif item['status'] != '2' and (not op_station or item['op_station'] == op_station) and item['strategyType'] == COMMON_STRATEGY_TYPE:
                        trades.append(item)
                    else:
                        continue
                    continue
                elif strategy_type == 'trade':
                    if item['status'] in ('0', '5'):
                        trades.append(item)
                    else:
                        continue
                    continue
                elif strategy_type == 'current_trade':
                    if item['status'] in ('0', '5') and item['ip'] == LOCAL_IP:
                        trades.append(item)
                    continue
                elif strategy_type == 'strategy_active_deleted':
                    if item['status'] in ('0', '5'):
                        trades.append(item)
                    continue
                elif item['status'] in ('0', '5') and item['strategyType'] == str(strategy_type):
                    trades.append(item)
        if strategy_type == 'strategy_active_deleted' and len(trades) > 0:
            trades = [item for item in trades if item.get('channel_type') == 'app']
            trades_dict = {}
            for item in trades:
                backtest_content_id = item.get('backtestContentId')
                if backtest_content_id:
                    trades_dict[backtest_content_id] = item
            trades = list(trades_dict.values())
    except BaseException:
        app_log.error(f'读取{trade_list_file!s}文件失败，错误原因：{get_traceback_message()!s}')
    return trades
def get_trade_strategy(user_id, trade_id):
    usercode_dat_file = os.path.join(TRADE_DIR_PATH, user_id, 'result', trade_id, USER_CODE_DAT)
    strategy_profile_file_path = os.path.join(STRATEGY_DIR_PATH, user_id, STRATEGY_PROFILE)
    if os.path.exists(usercode_dat_file):
        strategy = json.JSONDecoder().decode(json.load(open(usercode_dat_file, 'r')))
        strategy_id = strategy.get('id')
        if strategy['business_mode'] == BUSINESS_MODE_1:
            strategy['content'] = ''
        elif 'is_encryption' in strategy.keys() and strategy['is_encryption'] in (ENCRYPTION_MODE_1, ENCRYPTION_MODE_2):
            error_no, error_info, session_key, session_iv = PyRead_AES_Binary(strategy_profile_file_path, strategy_id)
            if error_no == 0:
                strategy['content'] = aes_decrypt(strategy['content'], session_key.decode('utf-8'), session_iv.decode('utf-8'))
            else:
                app_log.info('error_encryption:%s' % error_info)
        return strategy
    else:
        return None
def trade_operation(user_id, trade_id, operation):
    """
    交易状态设置
    """
    trade_list_file = os.path.join(TRADE_DIR_PATH, user_id, SIM_TRADING_LIST_FILE)
    delete_trade_list_file = os.path.join(TRADE_DIR_PATH, user_id, DELETE_SIM_TRADING_LIST_FILE)
    if isinstance(trade_id, str):
        trade_id_list = [trade_id]
    elif isinstance(trade_id, list):
        trade_id_list = trade_id
    else:
        app_log.error('不支持的trade_id入参类型%s' % type(trade_id))
        return False
    try:
        if os.path.exists(trade_list_file):
            with FileLock(trade_list_file):
                file_io = FileIO(trade_list_file)
                csv_reader = file_io.read(return_type='csv_reader')
                write_info = []
                delete_write_info = []
                new_file_flag = False
                if not os.path.exists(delete_trade_list_file):
                    new_file_flag = True
                    delete_write_info.append(SIM_TRADING_COLUMN_NAMES)
                for items in csv_reader:
                    if items[0] in trade_id_list:
                        if operation == 'start':
                            items[2] = '0'
                            operation = 'restart'
                        if operation == 'stop':
                            items[2] = '1'
                        if operation == 'delete':
                            items[2] = '2'
                            delete_write_info.append(items)
                            TradeOperationLogger(user_id, items[0]).write(operation)
                            continue
                        if operation == 'pause':
                            items[2] = '3'
                        if operation == 'reload':
                            items[2] = '4'
                        TradeOperationLogger(user_id, items[0]).write(operation)
                    write_info.append(items)
                if len(write_info) > 0:
                    file_io.write(write_info, mode='w', data_type='list')
                    if len(delete_write_info) > 0:
                        mode = 'w' if new_file_flag else 'a'
                        with FileLock(delete_trade_list_file):
                            FileIO(delete_trade_list_file).write(delete_write_info, mode=mode, data_type='list')
                    return True
                app_log.warning(f'用户{user_id!s}交易记录为空，无法执行{operation!s}操作')
                return False
            return None
        else:
            app_log.warning(f'用户{user_id!s}交易记录文件不存在，无法执行{operation!s}操作')
            return False
    except BaseException:
        app_log.error(f'用户{user_id!s}更新交易状态失败，错误原因：{get_traceback_message()!s}')
        return False
class TradeOperationLogger(object):
    __doc__ = """
    用于交易页面的操作打入前端界面日志信息
    """
    header = """time,user,backtest_id,level,opration
"""
    def __init__(self, user_id, backtest_id, type=None, message=None):
        self.base_path = f'{TRADE_DIR_PATH!s}/{user_id!s}/{USER_OPERATIONS_FILE!s}'
        self.csv_line = f'%s,{user_id!s},{backtest_id!s},%s,%s\n'
        if type is not None:
            getattr(self, type)(message)
            return None
        else:
            return None
    def write(self, message, level=0):
        d = datetime.datetime.now()
        add_header = not os.path.exists(self.base_path)
        with open(self.base_path, 'a') as log_file:
            if add_header:
                log_file.write(self.header)
            message = self.csv_line % (d.strftime('%Y-%m-%d %H:%M:%S'), level, message)
            log_file.write(message)
            return None
def check_trade_oom(user_id, trade_id, operation):
    if operation not in ('stop', 'delete'):
        return None
    else:
        status = get_mem_under_oom_status(user_id)
        if status['error_no'] == 1:
            kill_trade_proc(user_id, trade_id)
            app_log.error('%s,交易已终止' % status['error_info'])
            return None
        else:
            return None
