def get_crontab_param(trade_id):
    trade_record_file = os.path.join(trades_download_path, TRADES_DOWNLOAD_FILE)
    try:
        trade_crontab_df = pd.read_csv(trade_record_file, header=0, dtype=str, keep_default_na=False, index_col=False)
        trade_crontab_info_df = trade_crontab_df.query("trade_id == '%s'" % trade_id)
        if not trade_crontab_info_df.empty:
            crontab_time = trade_crontab_info_df['crontab_time'].values[0]
            save_path = trade_crontab_info_df['save_path'].values[0]
            flag = trade_crontab_info_df['flag'].values[0]
        else:
            crontab_time = ''
            save_path = ''
            flag = '0'
        crontab_param = {'crontab_time': crontab_time, 'save_path': save_path, 'flag': flag}
        return crontab_param
    except BaseException:
        app_log.info('读取定时任务信息出现异常:%s' % get_traceback_message())
        crontab_param = {'crontab_time': '', 'save_path': '', 'flag': '0'}
        return crontab_param
def cancel_order(trade_account, trade_id, user_id, entrust_no, business_type, exchange_type):
    """
    撤单接口
    @param trade_account: 账户对象
    @type trade_account: object
    @param trade_id: 交易ID
    @type trade_id: str
    @param user_id: 用户ID
    @type user_id: str
    @param entrust_no: 委托编号
    @type entrust_no: str
    @param business_type: 业务类型
    @type business_type: str
    @param exchange_type: 市场类别
    @type exchange_type: str
    """
    try:
        trade_unit = get_trade_unit(user_id, trade_id)
        request = {'entrust_no': entrust_no, 'business_type': business_type, 'exchange_type': exchange_type}
        if isinstance(trade_unit, list):
            if business_type in ('stock', 'rzrq'):
                trade_unit = trade_unit[0]
                request['trade_unit'] = trade_unit
            else:
                trade_unit = trade_unit[1]
                request['future_trade_unit'] = trade_unit
        elif business_type in ('stock', 'rzrq'):
            request['trade_unit'] = trade_unit
        else:
            request['future_trade_unit'] = trade_unit
        if business_type == 'rzrq':
            return trade_account.func_secu_rzrq_entrust_withdraw(**(request))
        elif business_type == 'future':
            return trade_account.func_future_entrust_withdraw(**(request))
        elif business_type == 'option':
            return trade_account.security_withdraw(**(request))
        elif business_type == 'hks':
            return trade_account.func_hks_security_withdraw(**(request))
        else:
            return trade_account.security_withdraw(**(request))
    except BaseException:
        error_message = get_traceback_message()
        return ({'error_no': -1, 'error_info': error_message}, {})
def get_trade_unit(user_id, trade_id):
    trade_unit = None
    base_path_user = os.path.join(base_path, user_id)
    user_info_path = '%s/user_info.csv' % base_path_user
    user_info = get_user_info_from_json(user_id)
    account_type = user_info['account_type']
    if account_type in ('PBOX_UFX_INTERFACE', 'PTRADE_INTERFACE'):
        trade_unit = user_id
    elif os.path.exists(user_info_path):
        user_info_trade = get_user_info(user_id, trade_id)
        if len(user_info_trade) <= 6:
            trade_unit = user_info_trade[4]
        else:
            trade_unit = [user_info_trade[4], user_info_trade[6]]
    return trade_unit
def get_user_info(user_id, trade_id):
    user_info_file = f'{TRADE_DIR_PATH!s}/{user_id!s}/{USER_INFO_FILE!s}'
    if os.path.exists(user_info_file):
        fp = None
        try:
            fp = open(user_info_file, 'r')
            csv_r = csv.reader(fp)
            for item in csv_r:
                if item[0] == trade_id:
                    return item
        except BaseException as x:
            app_log.exception(x)
        finally:
            if fp is not None:
                fp.close()
    return None
def get_last_stat(user_id, trade_id):
    result_data = {'data': {'stat': {'alpha': {'time': [], 'value': []}, 'beta': {'time': [], 'value': []}, 'sharpe': {'time': [], 'value': []}, 'sortino': {'time': [], 'value': []}, 'information': {'time': [], 'value': []}, 'volatility': {'time': [], 'value': []}, 'benchmark_volatility': {'time': [], 'value': []}, 'max_drawdown': {'time': [], 'value': []}, 'algorithm_return': {'time': [], 'value': []}, 'benchmark_return': {'time': [], 'value': []}, 'annual_algo_return': {'time': [], 'value': []}, 'trading_days': {'time': [], 'value': []}}, 'state': '1', 'offset': '-1', 'count': 1}, 'status': '0', 'code': '00000', 'msg': ''}
    pattren = re.compile('^a_')
    pattren1 = re.compile('^testds_to_json')
    count = 0
    testds_file_dir = f'{TRADE_DIR_PATH!s}/{user_id!s}/result/{trade_id!s}/'
    paths = []
    for parent, dirnames, filenames in os.walk(testds_file_dir):
        for fi in filenames:
            if pattren1.match(fi):
                paths.append(parent + fi)
    paths.sort()
    offset = len(paths)
    if offset >= 1:
        path = paths[offset - 1]
        fp = open(path, 'rb')
        try:
            readob = fp.read()
            readob = readob.decode('utf-8', 'ignore')
            if readob == 'end':
                if not fp:
                    fp.close()
                offset = len(paths)
                path = paths[offset - 2]
                fp = open(path, 'rb')
                readob = fp.read()
                readob = readob.decode('utf-8', 'ignore')
            readjson = json.loads(readob)
            UTC_FORMAT = '%Y-%m-%dT%H:%M:%S.%fZ'
            lasttime = readjson['index'][len(readjson['index']) - 1]
            date = datetime.datetime.strptime(lasttime, UTC_FORMAT) + datetime.timedelta(hours=8)
            lasttime = int(time.mktime(date.timetuple()) * 1000)
            result_data['data']['stat']['alpha']['time'].append(lasttime)
            result_data['data']['stat']['beta']['time'].append(lasttime)
            result_data['data']['stat']['sharpe']['time'].append(lasttime)
            result_data['data']['stat']['sortino']['time'].append(lasttime)
            result_data['data']['stat']['information']['time'].append(lasttime)
            result_data['data']['stat']['volatility']['time'].append(lasttime)
