                    files.append(f'{BASE_DIR!s}{type_dir!s}/{stock_dir!s}/{stock_code!s}/{start_year!s}.csv')
                    start_year += 1
                start_time = int(start[0:8] + (start[8:12] or '0900'))
                end_time = int(end[0:8] + (end[8:12] or '1530'))
            elif typet == 4:
                type_dir = '30minute'
