def filter_duplicated_date(klines):
    """
    去除重复数据
    """
    klines['date'] = klines.index
    isdup = list(klines.duplicated(['date']))
    if True in isdup:
        klines = klines.drop_duplicates(['date'])
    del klines['date']
    return klines
