class func_wrapper(object):
    def __init__(self, func):
        self.func = func
    def __call__(self, *args, **kwargs):
        result = self.func(*args, **(kwargs))
        return result
    @property
    def __name__(self):
        return self.func.__name__
class data_proxy(object):
    instance = None
    def __new__(cls, *args, **kwargs):
        if not cls.instance:
            cls.instance = super(data_proxy, cls).__new__(cls, *args, **(kwargs))
            for handler in handlers:
                setattr(cls.instance, handler.__name__, func_wrapper(handler))
        return cls.instance
    def __init__(self):
        return None
